def apply_clarifications(apps, schema_editor):
    RuleSet = apps.get_model('screening', 'RuleSet')
    for name, values in CHANGES.items():
        for rule in RuleSet.objects.using(schema_editor.connection.alias).filter(programme=name, admission_type='ND Full-Time', source='MAPOLY ND Full-Time compendium supplied by project owner'):
            criteria = dict(rule.criteria)
            criteria['jamb_groups'] = values['jamb_groups']
            # Remove only the original clarification, retaining unrelated staff notes.
            obsolete = {
                'Confirm the three UTME subjects belong to the social science, arts or physical science categories stated in the compendium.',
                'The supplied UTME combination does not unambiguously specify four subjects: English Language, Mathematics, Biology/Agricultural Science or Physics. Confirm the complete combination.',
                'The UTME wording says two other subjects from course requirement without an explicit UTME list. Confirm the permitted subjects.',
            }
            criteria['review_notes'] = [n for n in criteria.get('review_notes', []) if n not in obsolete]
            criteria['advisories'] = list(dict.fromkeys(criteria.get('advisories', []) + values['advisories']))
            criteria['source_text'] = values['source_text']
            rule.criteria = criteria
            rule.revision += 1
            rule.save(update_fields=['criteria', 'revision', 'updated_at'])

class Migration(migrations.Migration):
    dependencies = [('screening', '0004_confirm_electrical_sittings')]
    operations = [migrations.RunPython(apply_clarifications, migrations.RunPython.noop)]
